@app.get('/eventos')
def eventos():
    def gerar():
        for etapa in range(1, 4):
            yield f'id: {etapa}\ndata: {json.dumps({"etapa": etapa})}\n\n'
            time.sleep(1)
    return Response(gerar(), mimetype='text/event-stream',
        headers={'Cache-Control': 'no-cache', 'X-Accel-Buffering': 'no'})

