class CriarPedido:
    def __init__(self, pedidos):
        self.pedidos = pedidos

    def executar(self, pedido_id, total_centavos):
        if type(total_centavos) is not int or total_centavos <= 0:
            raise ValueError('Total inválido')
        if pedido_id in self.pedidos:
            raise ValueError('Pedido já existe')
        pedido = {'id': pedido_id, 'total_centavos': total_centavos}
        self.pedidos[pedido_id] = pedido
        return pedido.copy()

