def converter(linhas):
    for numero, texto in enumerate(linhas, start=1):
        try:
            yield numero, int(texto)
        except ValueError as erro:
            raise ValueError(f'Linha {numero}: inteiro inválido') from erro

def positivos(registros):
    for numero, valor in registros:
        if valor > 0:
            yield numero, valor

entrada = ['10', '-2', '7']
print(list(positivos(converter(entrada))))

def normalizar_csv(texto):
    return [campo.strip() for campo in texto.split(',')]

def normalizar_linhas(texto):
    return texto.splitlines()

plugins = {'csv-simples': normalizar_csv, 'linhas': normalizar_linhas}

def processar(nome, texto):
    if nome not in plugins:
        raise ValueError('Plugin não habilitado')
    return plugins[nome](texto)

