@dataclass(frozen=True)
class Cotacao:
    preco_centavos: int
    moeda: str
    prazo_dias: int

def cotar_transporte(peso_gramas: int) -> Cotacao:
    if type(peso_gramas) is not int or peso_gramas <= 0:
        raise ValueError('Peso deve ser inteiro positivo em gramas')
    blocos = (peso_gramas + 999) // 1000
    return Cotacao(preco_centavos=blocos * 800, moeda='BRL', prazo_dias=3)

